#' Aggregate trajectory windows into MetaCells
#'
#' Aggregates the expression counts and cell-type annotations from a list
#' of Seurat objects representing consecutive trajectory windows.
#' Each window is converted into one MetaCell, with summed gene counts
#' and metadata describing its rank, number of cells, and cell-type
#' composition.
#'
#' @param window.list Named list of Seurat objects generated by
#'   `generate_trajectory_metacells()`.
#' @param anno.col Name of the metadata column containing cell-type
#'   annotations to aggregate. Defaults to `"cell_anno"`.
#'
#' @return A Seurat object containing one MetaCell per trajectory window.
#'   The expression counts are summed across cells within each window.
#'   Metadata includes `MetaCell_rank`, `MetaCell_ncells`, and one
#'   column per cell type containing its cell count.
#'
#' @importFrom Matrix rowSums
#' @export
aggregate_trajectory_metacells <- function(
    window.list,
    anno.col = "cell_anno"
) {
  
  meta.list <- list()
  count.list <- list()
  
  for (i in seq_along(window.list)) {
    win <- window.list[[i]]
    
    # --- Access counts ---
    counts <- get_assay_data(win, what = "counts")
    counts <- Matrix::rowSums(counts)
    count.list[[i]] <- counts
    
    # --- Build metadata ---
    MetaCell_rank <- i
    meta <- win@meta.data
    
    if (!anno.col %in% colnames(meta)) {
      stop(paste("Column", anno.col, "not in metadata"))
    }
    
    # Aggregate annotation counts
    anno.tab <- table(meta[[anno.col]])
    anno.list <- as.list(anno.tab)
    
    # Combine metadata
    meta.list[[i]] <- c(
      list(MetaCell_rank = MetaCell_rank, MetaCell_ncells = nrow(meta)),
      anno.list
    )
  }
  
  # Determine annotation columns
  anno.cols <- unique(unlist(lapply(meta.list, function(x) setdiff(names(x), c("MetaCell_rank", "MetaCell_ncells")))))
  
  # Build metadata dataframe with consistent column order
  df <- do.call(rbind, lapply(meta.list, function(x) {
    for (a in anno.cols) {
      if (!a %in% names(x)) x[[a]] <- 0
    }
    x[c("MetaCell_rank", "MetaCell_ncells", anno.cols)]
  }))
  
  df <- as.data.frame(df)
  rownames(df) <- names(window.list)
  
  # Convert numeric-like columns to numeric
  df$MetaCell_rank <- as.numeric(df$MetaCell_rank)
  df$MetaCell_ncells <- as.numeric(df$MetaCell_ncells)
  
  for (col in anno.cols) {
    if (all(grepl("^[0-9\\.]+$", df[[col]]))) {
      df[[col]] <- as.numeric(df[[col]])
    }
  }
  
  # --- Build count matrix ---
  count.mat <- do.call(cbind, count.list)
  colnames(count.mat) <- names(window.list)
  
  # --- Create Seurat object ---
  meta.obj <- SeuratObject::CreateSeuratObject(
    counts = count.mat,
    meta.data = df
  )
  
  return(meta.obj)
}
